package system

import (
	"errors"
	"fmt"
	"path/filepath"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// ErrNoComponents is returned when the workspace scan finds no scaffold
// record `sys create` can assemble into a component.
var ErrNoComponents = errors.New("no assemblable integration scaffolds found")

// Assemble classifies workspace scaffold records into a system model:
// shared-library records become the referenced contract project,
// extractor/loader records become components, and everything else is
// skipped through warnf. The returned model's Name/ProjectName/SystemClass
// are left empty — the caller fills them around the template render.
func Assemble(entries []template.ScaffoldEntry, warnf func(format string, args ...any)) (*Model, error) {
	var (
		components  []Component
		shared      []SharedLibrary
		byAppID     = map[string]string{}   // appId -> scaffold dir
		byTopic     = map[TopicKey]Topic{}  // key -> first-seen topic
		firstDir    = map[TopicKey]string{} // key -> dir that defined it
		byConnector = map[string]string{}   // connector -> scaffold dir
	)

	for _, e := range entries {
		switch {
		case e.Role == template.RoleSharedLibrary:
			name, err := stringValue(e, "name")
			if err != nil {
				return nil, err
			}
			shared = append(shared, SharedLibrary{Path: e.Path, Name: name})
			continue
		case e.Role == template.RoleSystemHost:
			warnf("skipping %s: an existing system host", e.Path)
			continue
		case e.BlockKind == "":
			warnf("skipping %s: scaffold record has no block kind — re-scaffold with a newer template release to include it", e.Path)
			continue
		case e.BlockKind != template.BlockKindExtractor && e.BlockKind != template.BlockKindLoader:
			warnf("skipping %s: unsupported block kind %q (sys create assembles extractors and loaders only)", e.Path, e.BlockKind)
			continue
		}

		appID, err := stringValue(e, "appId")
		if err != nil {
			return nil, err
		}
		topic, err := stringValue(e, "topic")
		if err != nil {
			return nil, err
		}
		contract, err := stringValue(e, "contract")
		if err != nil {
			return nil, fmt.Errorf("%w\nRe-scaffold this integration with a template release that records the contract type, or add \"contract\": \"<TypeName>\" to the record's values.", err)
		}
		pubsub, err := stringValueDefault(e, "pubsub", "pubsub")
		if err != nil {
			return nil, err
		}
		// No CLI-side fallback for the connector: a default would describe a
		// binding the rendered code doesn't use. A component without one is
		// valid topology — it just gets no From/To.
		connector := ""
		if _, ok := e.Values["connector"]; ok {
			if connector, err = stringValue(e, "connector"); err != nil {
				return nil, err
			}
		} else {
			warnf("%s: scaffold record has no connector — re-scaffold with a newer template release to wire From/To", e.Path)
		}

		if prev, ok := byAppID[appID]; ok {
			return nil, fmt.Errorf("duplicate component name %q: declared by both %s and %s (component names must be unique in a system)", appID, prev, e.Path)
		}
		byAppID[appID] = e.Path

		if connector != "" {
			if prev, ok := byConnector[connector]; ok {
				return nil, fmt.Errorf("duplicate connector %q: declared by both %s and %s (each edge block gets its own port; rename one in the record's values)", connector, prev, e.Path)
			}
			byConnector[connector] = e.Path
		}

		key := TopicKey{Pubsub: pubsub, Name: topic}
		if seen, ok := byTopic[key]; ok {
			if seen.Contract != contract {
				return nil, fmt.Errorf("topic %q on pubsub %q has conflicting contracts: %q (%s) vs %q (%s)", topic, pubsub, seen.Contract, firstDir[key], contract, e.Path)
			}
		} else {
			byTopic[key] = Topic{TopicKey: key, Contract: contract, Field: pascalIdent(topic)}
			firstDir[key] = e.Path
		}

		components = append(components, Component{AppID: appID, Kind: e.BlockKind, Topic: key, Connector: connector, Path: e.Path})
	}

	if len(components) == 0 {
		return nil, fmt.Errorf("%w in this directory\nScaffold extractors and loaders first ('intropy int create extractor -n <Name> -s topic=<topic> ...'), then run 'intropy sys create' from the workspace root.", ErrNoComponents)
	}
	switch {
	case len(shared) == 0:
		return nil, fmt.Errorf("no shared contracts project found (template role %q): Topics.cs needs the contract types\nComponents scaffolded from the official extractor/loader templates create a sibling Contracts/ project automatically.", template.RoleSharedLibrary)
	case len(shared) > 1:
		dirs := make([]string, len(shared))
		for i, s := range shared {
			dirs[i] = s.Path
		}
		return nil, fmt.Errorf("found %d shared contract projects (%s); a system host references exactly one — remove or consolidate before re-running", len(shared), strings.Join(dirs, ", "))
	}

	topics := make([]Topic, 0, len(byTopic))
	for _, t := range byTopic {
		topics = append(topics, t)
	}
	sort.Slice(topics, func(i, j int) bool {
		if topics[i].Pubsub != topics[j].Pubsub {
			return topics[i].Pubsub < topics[j].Pubsub
		}
		return topics[i].Name < topics[j].Name
	})

	fields := map[string]TopicKey{}
	for _, t := range topics {
		if prev, ok := fields[t.Field]; ok {
			return nil, fmt.Errorf("topics %q (pubsub %q) and %q (pubsub %q) both map to field %s in Topics.cs; rename one topic", prev.Name, prev.Pubsub, t.Name, t.Pubsub, t.Field)
		}
		fields[t.Field] = t.TopicKey
	}

	connectors := make([]Connector, 0, len(byConnector))
	for name := range byConnector {
		connectors = append(connectors, Connector{Name: name, Field: pascalIdent(name)})
	}
	sort.Slice(connectors, func(i, j int) bool { return connectors[i].Name < connectors[j].Name })
	connectorFields := map[string]string{}
	for _, c := range connectors {
		if prev, ok := connectorFields[c.Field]; ok {
			return nil, fmt.Errorf("connectors %q and %q both map to field %s in Connectors.cs; rename one in the record's values", prev, c.Name, c.Field)
		}
		connectorFields[c.Field] = c.Name
	}

	return &Model{Components: components, Topics: topics, Connectors: connectors, Shared: shared[0]}, nil
}

// stringValue returns values[key] as a non-empty string, with errors that
// name the record so the user knows which project to fix.
func stringValue(e template.ScaffoldEntry, key string) (string, error) {
	record := filepath.Join(e.Path, filepath.FromSlash(template.ScaffoldRelPath))
	v, ok := e.Values[key]
	if !ok {
		return "", fmt.Errorf("%s: values.%s is missing", record, key)
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%s: values.%s has type %T, expected string", record, key, v)
	}
	if s == "" {
		return "", fmt.Errorf("%s: values.%s is empty", record, key)
	}
	return s, nil
}

// stringValueDefault is stringValue with a fallback for records that
// predate the value being recorded.
func stringValueDefault(e template.ScaffoldEntry, key, fallback string) (string, error) {
	if _, ok := e.Values[key]; !ok {
		return fallback, nil
	}
	return stringValue(e, key)
}

// pascalIdent converts a DNS-ish name to a C# identifier: segments split
// on '-', '.' and '_' are title-cased and joined ("order-events" →
// "OrderEvents").
func pascalIdent(s string) string {
	segments := strings.FieldsFunc(s, func(r rune) bool {
		return r == '-' || r == '.' || r == '_'
	})
	var b strings.Builder
	for _, seg := range segments {
		b.WriteString(strings.ToUpper(seg[:1]))
		b.WriteString(seg[1:])
	}
	return b.String()
}

package template

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

const (
	// ScaffoldSchemaVersion is the newest scaffold.json schema this CLI
	// understands. Bump only for incompatible changes; additive fields do
	// not require a bump.
	ScaffoldSchemaVersion = 1

	// ScaffoldRelPath is where the scaffold record lives inside a project.
	ScaffoldRelPath = ".intropy/scaffold.json"

	// TemplateRoleLabel names the manifest label that declares what role a
	// template's output plays in a system. Its value is copied into the
	// scaffold record so later commands can tell support projects apart
	// from system blocks.
	TemplateRoleLabel = "intropy.dev/template-role"

	// RoleSharedLibrary marks a scaffolded project that exists to be
	// referenced by sibling components (e.g. shared models). System
	// assembly must not treat it as a block.
	RoleSharedLibrary = "shared-library"

	// RoleSystemHost marks the scaffolded host project of an integration
	// system. System assembly must not treat it as a block.
	RoleSystemHost = "system-host"

	// TemplateBlockKindLabel names the manifest label that declares which
	// Intropy block a template scaffolds (e.g. "extractor"). Its value is
	// copied into the scaffold record so `sys create` can assemble the
	// system declaration from what each scaffold recorded.
	TemplateBlockKindLabel = "intropy.dev/block-kind"

	// TemplateDataFlowLabel names the manifest label that declares the
	// block's data flow direction relative to the system ("in" or "out").
	// Recorded alongside the block kind.
	TemplateDataFlowLabel = "intropy.dev/data-flow"

	// BlockKindExtractor and BlockKindLoader are the block kinds `sys
	// create` knows how to assemble.
	BlockKindExtractor = "extractor"
	BlockKindLoader    = "loader"
)

var ErrScaffoldNotFound = errors.New("no " + ScaffoldRelPath + " found in current directory or any parent")

// Scaffold is the committed record of what `int create` rendered. Unlike
// CreateResult it carries no outputDir — the file's location is the project
// root — and it is written into the project so later commands (e.g. `sys
// create`) can re-fetch the exact template version.
type Scaffold struct {
	SchemaVersion int            `json:"schemaVersion"`
	Template      string         `json:"template"` // directory name in the template library repo
	Owner         string         `json:"owner"`
	Repo          string         `json:"repo"`
	Version       string         `json:"version"`
	Values        map[string]any `json:"values"`

	// Role is the value of the template's intropy.dev/template-role label,
	// if any (e.g. "shared-library").
	Role string `json:"role,omitempty"`

	// BlockKind is the value of the template's intropy.dev/block-kind
	// label, if any (e.g. "extractor").
	BlockKind string `json:"blockKind,omitempty"`

	// DataFlow is the value of the template's intropy.dev/data-flow label,
	// if any ("in" or "out").
	DataFlow string `json:"dataFlow,omitempty"`

	// DependsOn lists the sibling projects this project's template declared
	// under spec.dependencies, whether the render created them or they
	// already existed.
	DependsOn []DependencyRecord `json:"dependsOn,omitempty"`
}

// DependencyRecord points at a sibling project a component depends on. Dir
// is slash-separated and relative to the component root (e.g. "../Acme.Models").
type DependencyRecord struct {
	Template string `json:"template"`
	Dir      string `json:"dir"`
}

func roleFromLabels(labels map[string]string) string {
	return labels[TemplateRoleLabel]
}

func blockKindFromLabels(labels map[string]string) string {
	return labels[TemplateBlockKindLabel]
}

func dataFlowFromLabels(labels map[string]string) string {
	return labels[TemplateDataFlowLabel]
}

// WriteScaffold writes the scaffold record to <projectRoot>/.intropy/scaffold.json.
func WriteScaffold(projectRoot string, s Scaffold) error {
	path := filepath.Join(projectRoot, filepath.FromSlash(ScaffoldRelPath))
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	data = append(data, '\n')
	if err := os.WriteFile(path, data, 0o644); err != nil {
		return fmt.Errorf("write scaffold record: %w", err)
	}
	return nil
}

// LoadScaffold reads and parses a scaffold.json file.
func LoadScaffold(path string) (*Scaffold, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read scaffold record %s: %w", path, err)
	}
	var s Scaffold
	if err := json.Unmarshal(data, &s); err != nil {
		return nil, fmt.Errorf("parse scaffold record %s: %w", path, err)
	}
	return &s, nil
}

// FindScaffold walks up from startDir looking for .intropy/scaffold.json.
// Returns the parsed record and the project root that contains it, or
// ErrScaffoldNotFound if the filesystem root is reached first.
func FindScaffold(startDir string) (*Scaffold, string, error) {
	abs, err := filepath.Abs(startDir)
	if err != nil {
		return nil, "", fmt.Errorf("absolute path: %w", err)
	}

	for {
		candidate := filepath.Join(abs, filepath.FromSlash(ScaffoldRelPath))
		if _, err := os.Stat(candidate); err == nil {
			s, err := LoadScaffold(candidate)
			if err != nil {
				return nil, "", err
			}
			return s, abs, nil
		} else if !os.IsNotExist(err) {
			return nil, "", fmt.Errorf("stat %s: %w", candidate, err)
		}

		parent := filepath.Dir(abs)
		if parent == abs {
			return nil, "", ErrScaffoldNotFound
		}
		abs = parent
	}
}

// Package system assembles scaffolded integrations into a system host. It
// scans the workspace for the .intropy/scaffold.json records `int create`
// left behind, validates them into a system model, and builds the value
// payload the system-host template renders every declaration file from —
// Topics.cs, Connectors.cs, the development and system definitions, and
// the csproj. The template library owns all generated content; this
// package owns workspace knowledge only.
package system

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/huandu/xstrings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// hostTemplate is the directory in the templates repo holding the system
// host: the shell plus every declaration file, rendered from the payload.
const hostTemplate = "system-host"

type CreateOptions struct {
	Name       string // system name as typed; PascalCase or kebab-case
	StartDir   string // workspace scan root; default "."
	OutputDir  string // default: the kebab-cased name
	Version    string // template release tag; default: latest
	Force      bool
	OutputJSON string // path to write CreateResult JSON; "-" means stdout
	Stdout     io.Writer
	Stderr     io.Writer
	HTTP       *http.Client
	UserAgent  string

	// Owner and Repo select the template library; zero values target the
	// official library. GitHubBaseURL is a test-only seam.
	Owner         string
	Repo          string
	GitHubBaseURL string
}

// CreateResult is the machine-readable summary written when --output-json
// is set. Field names are stable and additive-only.
type CreateResult struct {
	Template  string         `json:"template"`
	Owner     string         `json:"owner"`
	Repo      string         `json:"repo"`
	Version   string         `json:"version"`
	OutputDir string         `json:"outputDir"`
	Values    map[string]any `json:"values"`
	System    Summary        `json:"system"`
}

// Summary describes the assembled system; it loosely mirrors the model the
// host's `graph` verb prints.
type Summary struct {
	Name          string      `json:"name"`
	Components    []Component `json:"components"`
	Topics        []Topic     `json:"topics"`
	Connectors    []Connector `json:"connectors,omitempty"`
	SharedLibrary string      `json:"sharedLibrary"` // scaffold directory
}

func (o *CreateOptions) applyDefaults() {
	if o.StartDir == "" {
		o.StartDir = "."
	}
	if o.Stdout == nil {
		o.Stdout = os.Stdout
	}
	if o.Stderr == nil {
		o.Stderr = os.Stderr
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
}

// Create runs the full assembly: scan the workspace for scaffold records,
// validate them into a system model, build the value payload, and render
// the system-host template with it. All local validation happens before
// any network I/O.
func Create(ctx context.Context, opts CreateOptions) error {
	opts.applyDefaults()
	if opts.Name == "" {
		return fmt.Errorf("a system name is required")
	}

	// Exact parity with the templates' `{{ .name | kebabcase }}`: sprig
	// delegates to xstrings, so OrderFlow and order-flow are equivalent.
	kebab := xstrings.ToKebabCase(opts.Name)
	if opts.OutputDir == "" {
		opts.OutputDir = kebab
	}

	entries, warnings := template.ListScaffolds(opts.StartDir)
	for _, w := range warnings {
		fmt.Fprintf(opts.Stderr, "warning: %v\n", w)
	}
	warnf := func(format string, args ...any) {
		fmt.Fprintf(opts.Stderr, "warning: "+format+"\n", args...)
	}
	model, err := Assemble(entries, warnf)
	if err != nil {
		return err
	}
	model.Name = kebab

	payload, err := buildPayload(model, opts.OutputDir, kebab)
	if err != nil {
		return err
	}

	if err := template.Create(ctx, template.CreateOptions{
		Template:      hostTemplate,
		OutputDir:     opts.OutputDir,
		Version:       opts.Version,
		SetValues:     payload,
		Force:         opts.Force,
		NoInput:       true, // the template's values come from the payload, never prompts
		Stdin:         strings.NewReader(""),
		Stdout:        opts.Stdout,
		Stderr:        opts.Stderr,
		HTTP:          opts.HTTP,
		UserAgent:     opts.UserAgent,
		Owner:         opts.Owner,
		Repo:          opts.Repo,
		GitHubBaseURL: opts.GitHubBaseURL,
	}); err != nil {
		return err
	}

	// The template derives projectName/systemClass from the name; reading
	// them back from the record it just wrote keeps the result summary
	// honest about what was rendered.
	record, err := template.LoadScaffold(filepath.Join(opts.OutputDir, filepath.FromSlash(template.ScaffoldRelPath)))
	if err != nil {
		return err
	}
	hostEntry := template.ScaffoldEntry{Path: opts.OutputDir, Scaffold: *record}
	if model.ProjectName, err = stringValue(hostEntry, "projectName"); err != nil {
		return fmt.Errorf("template %s did not derive the host project name: %w", hostTemplate, err)
	}
	if model.SystemClass, err = stringValue(hostEntry, "systemClass"); err != nil {
		return fmt.Errorf("template %s did not derive the system class name: %w", hostTemplate, err)
	}

	fmt.Fprintf(opts.Stderr, "assembled system %q: %d component(s), %d topic(s), %d connector(s), contracts from %s\n",
		model.Name, len(model.Components), len(model.Topics), len(model.Connectors), model.Shared.Path)

	return maybeWriteCreateResult(opts, record, model)
}

func maybeWriteCreateResult(opts CreateOptions, record *template.Scaffold, model *Model) error {
	if opts.OutputJSON == "" {
		return nil
	}
	absOut, err := filepath.Abs(opts.OutputDir)
	if err != nil {
		absOut = opts.OutputDir
	}
	result := CreateResult{
		Template:  hostTemplate,
		Owner:     record.Owner,
		Repo:      record.Repo,
		Version:   record.Version,
		OutputDir: absOut,
		Values:    record.Values,
		System: Summary{
			Name:          model.Name,
			Components:    model.Components,
			Topics:        model.Topics,
			Connectors:    model.Connectors,
			SharedLibrary: model.Shared.Path,
		},
	}
	data, err := json.MarshalIndent(result, "", "  ")
	if err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	data = append(data, '\n')
	if opts.OutputJSON == "-" {
		if _, err := opts.Stdout.Write(data); err != nil {
			return fmt.Errorf("write --output-json: %w", err)
		}
		return nil
	}
	if err := os.WriteFile(opts.OutputJSON, data, 0o644); err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	return nil
}

